/* 栏本体 */
.chat-detail-screen .chat-header-custom{background:var(--oo-bar)!important;-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px);border-bottom:0px solid var(--oo-line)!important;box-shadow:none}

