/* 标题居中 + 日夜 */
.chat-detail-screen .header-profile-section{position:absolute;left:50%;transform:translateX(-50%);align-items:center;justify-content:center;text-align:center;max-width:55%}
.chat-detail-screen .chat-header-title{color:var(--oo-ink)!important;font-size:17px;font-weight:800;text-align:center}
.chat-detail-screen .chat-header-title *{color:inherit!important}
