.chat-detail-screen .header-btn-back{display:flex;align-items:center;justify-content:center;font-size:0;color:transparent}
.chat-detail-screen .header-btn-back>*:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){display:none!important}
.chat-detail-screen .header-btn-back::before{content:"";width:12px;height:12px;border-left:3.5px solid var(--oo-ink);border-bottom:3.5px solid var(--oo-ink);border-bottom-left-radius:2px;transform:translateX(3px) rotate(45deg)}

/* 电话、视频：看不见但还能点 */
