    -0.057em 0.100em 0 #000, -0.081em 0.081em 0 #000, -0.100em 0.057em 0 #000, -0.111em 0.030em 0 #000,
    -0.115em 0.000em 0 #000, -0.111em -0.030em 0 #000, -0.100em -0.057em 0 #000, -0.081em -0.081em 0 #000,
