  --st-r: 16px;            /* 圆角 */
  --st-gap1: 9px;          /* 第二层往右露出多少 */
  --st-gap2: 18px;         /* 第三层往右露出多少 */
  --st-in1: 8px;           /* 第二层上下各缩进多少 */
  --st-in2: 16px;          /* 第三层上下各缩进多少 */

  --st-img1: url("https://imgbed.heliar.top/i/AoWSNPrYAvUTSCSf_IMG_1728.jpeg");
  --st-img2: url("https://imgbed.heliar.top/i/io2K1M6kBjymMS4Z_IMG_1726.jpeg");
  --st-f1: none;
  --st-f2: none;
}
body.dark-mode {
  --st-f1: grayscale(0.5) blur(1.5px) brightness(0.6);
  --st-f2: grayscale(0.9) blur(2.5px) brightness(0.45);
