/* ============================================================
   ⑨ 翻译：隐藏「查看翻译」，点气泡展开 → 白字黑描边
   ============================================================ */

/* 气泡内：翻译区脱离排版流，不占任何高度 */
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  overflow: visible !important;
  pointer-events: none !important;
  z-index: 3 !important;
}
