}

/* 气泡外：点开后出现的独立翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: -4px !important;
  max-width: 100% !important;
  width: fit-content !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 6 !important;
  pointer-events: none !important;
}
.msg-translation-detached-them { transform: translate(18px, -10px) !important; }
.msg-translation-detached-me   { transform: translate(-18px, -10px) !important; }

/* 翻译文字：去气泡，粗体 + 白字黑描边 */
